(function(){'use strict';document.addEventListener('DOMContentLoaded',function(){var latInput=document.getElementById('project_latitude');var lngInput=document.getElementById('project_longitude');var linkInput=document.getElementById('project_gps_source');var locateButton=document.getElementById('project_get_location');var statusEl=document.getElementById('project_gps_status');if(!latInput||!lngInput){return;}function getI18n(key,fallback){if(window.malisafiProjectGps&&window.malisafiProjectGps.i18n&&window.malisafiProjectGps.i18n[key]){return window.malisafiProjectGps.i18n[key];}return fallback;}function setStatus(message,type){if(!statusEl){return;}statusEl.textContent=message||'';statusEl.classList.remove('is-info','is-success','is-error');if(type){statusEl.classList.add('is-'+type);}}function setCoordinates(lat,lng){if(typeof lat!=='number'||typeof lng!=='number'){return;}if(lat<-90||lat>90||lng<-180||lng>180){return;}latInput.value=lat.toFixed(6);lngInput.value=lng.toFixed(6);}function parseCoordinates(value){if(!value){return null;}var text=value.trim();var match=text.match(/(-?\d{1,2}\.\d+)\s*[,]\s*(-?\d{1,3}\.\d+)/);if(match){return{lat:parseFloat(match[1]),lng:parseFloat(match[2])};}match=text.match(/@(-?\d{1,2}\.\d+),(-?\d{1,3}\.\d+)/);if(match){return{lat:parseFloat(match[1]),lng:parseFloat(match[2])};}match=text.match(/[?&](?:q|ll)=(-?\d{1,2}\.\d+),(-?\d{1,3}\.\d+)/);if(match){return{lat:parseFloat(match[1]),lng:parseFloat(match[2])};}match=text.match(/!3d(-?\d{1,2}\.\d+)!4d(-?\d{1,3}\.\d+)/);if(match){return{lat:parseFloat(match[1]),lng:parseFloat(match[2])};}return null;}function handleCoordinateSource(){if(!linkInput||!linkInput.value){return;}var parsed=parseCoordinates(linkInput.value);if(parsed){setCoordinates(parsed.lat,parsed.lng);setStatus(getI18n('parsed','Coordinates extracted from the link.'),'success');}else{setStatus(getI18n('invalid','Could not detect coordinates.'),'error');}}if(linkInput){linkInput.addEventListener('blur',handleCoordinateSource);linkInput.addEventListener('change',handleCoordinateSource);}if(locateButton){locateButton.addEventListener('click',function(){if(!navigator.geolocation){setStatus(getI18n('geoUnsupported','Geolocation is not supported in this browser.'),'error');return;}locateButton.disabled=true;setStatus(getI18n('locating','Locating your position...'),'info');navigator.geolocation.getCurrentPosition(function(position){setCoordinates(position.coords.latitude,position.coords.longitude);setStatus(getI18n('success','Coordinates updated.'),'success');locateButton.disabled=false;},function(error){var message=getI18n('unavailable','Location is currently unavailable.');if(error&&error.code===1){message=getI18n('permissionDenied','Location permission was denied.');}else if(error&&error.code===3){message=getI18n('timeout','Location request timed out.');}setStatus(message,'error');locateButton.disabled=false;},{enableHighAccuracy:true,timeout:10000,maximumAge:0});});}});})();